#!/usr/bin/env python3
"""Reconstruct fresh completed native planes from original words and original parser operands."""
import hashlib,json,re,struct,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=Path(sys.argv[1]).resolve();sha=lambda b:hashlib.sha256(b).hexdigest()
def need(v,why):
 if not v:raise AssertionError(why)
def words(raw):return list(struct.unpack('<'+'I'*(len(raw)//4),bytes(raw)))
def prediction(run):
 original=run['original'];tokens=run['originalTokens'][1];imms={i['index']:i['words'] for i in tokens['immediates']};instructions=tokens['textureInstructions'];need(len(instructions)==3,'original three texture instructions');fetch,lod,query=instructions;need(fetch['instruction']==1 and fetch['writeMask']==9 and lod['instruction']==2 and query['instruction']==5 and query['writeMask']==11,'original operation order and masks')
 images={i['slot']:i for i in original['images']};fsource=fetch['sources'][0];need(fsource['index']==0 and fsource['swizzle']==[1,0,2,3] and not fsource['absolute'] and not fsource['negate'],'original integer fetch source');coord=[imms[0][lane] for lane in fsource['swizzle']];image=images[fetch['sources'][1]['index']];plane=image['planes'][coord[3]];need(coord[0]<plane['width'] and coord[1]<plane['height'],'defined original fetch');raw=words(plane['bytes']);at=(coord[1]*plane['width']+coord[0])*4;r=raw[at:at+4];first=[r[0],imms[3][1],imms[3][2],r[3]]
 lsource=lod['sources'][0];need(lsource['index']==1 and lsource['swizzle']==[1,0,2,3] and lsource['absolute'] and not lsource['negate'],'original numeric coordinate absolute/swizzle');coord=[struct.unpack('<f',struct.pack('<I',imms[1][lane]&0x7fffffff))[0] for lane in lsource['swizzle']];need(coord[3]==1 and 0<=coord[0]<1 and 0<=coord[1]<1,'defined original float coordinates/LOD');image=images[lod['sources'][1]['index']];plane=image['planes'][int(coord[3])];x,y=int(coord[0]*plane['width']),int(coord[1]*plane['height']);raw=words(plane['bytes']);at=(y*plane['width']+x)*4;r=raw[at:at+4];need('3: MOV TEMP[1], -|TEMP[1].zyxw|' in original['fragmentText'],'literal original sampled word modifier');modified=[((r[lane]&0x7fffffff)^0x80000000) for lane in [2,1,0,3]];need(all(abs(struct.unpack('<f',struct.pack('<I',v))[0])>=2**-126 for v in modified),'finite normal float modifier truth')
 qsource=query['sources'][0];need(qsource['index']==2 and qsource['swizzle']==[0,0,0,0],'original integer query source');level=imms[2][0];image=images[query['sources'][1]['index']];need(0<=level<image['levels'],'defined original query level');queried=[max(1,image['width']>>level),max(1,image['height']>>level),imms[3][2],image['levels']]
 return {0:first,1:queried,3:modified}
def audit(name,fault):
 path=OUT/name/'report.json';report=json.loads(path.read_text());a=report['acceptance'];need(report['status']==('failed' if fault else 'passed'),'expected native result');need(report['browserErrors']=={'console':[],'page':[],'requests':[]},'zero native browser errors');need(not report['browser']['launch']['headless'] and report['browser']['gpu']['featureStatus'][report['browser']['webglFeature']]=='enabled','headed hardware');need('Apple M4 Max' in a['renderer'] and 'Metal' in a['renderer'],'actual Metal renderer');need(len(a['runs'])==(1 if fault else 3),'independent seeds');ids=[];planes=sourcewords=outputwords=0;mismatches=[]
 for i,run in enumerate(a['runs']):
  expected=prediction(run);need(run['predictedBeforeDraw']=={str(k):v for k,v in expected.items()},'before-draw independent original predictions');need(run['cleaned'],'native objects retired');need(run['original']['selectors']['signedColorMask']==1 and run['original']['selectors']['unsignedColorMask']==2,'host semantic output masks')
  for fence in run['fences']:
   need(fence['created'] and fence['ready'] and fence['retired'] and fence['nativeClass']=='WebGLSync','actual sync custody');need(fence['statuses'] and all(s in [0x911a,0x911b,0x911c] for s in fence['statuses']) and fence['statuses'][-1]==fence['finalStatus'] in [0x911a,0x911c],'complete native fence states');ids.append(fence['id'])
  need(len(run['fences'])==(2 if fault else 1),'native fence count')
  images={image['slot']:image for image in run['original']['images']}
  for p in run['sourcePlanes']:
   image=images[p['slot']];need(p['nativeWords']==words(p['originalBytes'])==words(image['planes'][p['level']]['bytes']),'whole original/native source planes');need(p['internal']==(0x8d82 if image['signed'] else 0x8d70) and p['type']==(0x1404 if image['signed'] else 0x1405),'native original image signedness');need(p['state']=={'slot':image['slot'],'base':0,'max':image['levels']-1,'immutableLevels':image['levels']},'native complete queried levels');sourcewords+=len(p['nativeWords']);planes+=1
  need(run['query']=={'name':'fssamplevels3','type':0x1404,'actualLevels':4},'native query reflection and levels');need(run['reflection']==[{'name':'fssamp3','slot':3,'type':0x8dd2,'size':1,'actualUnit':3},{'name':'fssamp15','slot':15,'type':0x8dca,'size':1,'actualUnit':15}],'native original sampler type/unit reflection')
  for output in run['outputs']:
   loc=output['location'];need(output['actualLocation']==loc,'native semantic locations');wanted=expected[loc]*(run['original']['frameWidth']*run['original']['frameHeight']);need(output['originalCompletedWords']==wanted,'whole original completed output');actual=output['nativeWords'];need(len(actual)==len(wanted),'whole output extent');outputwords+=len(actual)
   if actual!=wanted:mismatches.append({'run':i,'location':loc,'firstExpected':wanted[:4],'firstActual':actual[:4],'expectedSha256':sha(struct.pack('<'+'I'*len(wanted),*wanted)),'actualSha256':sha(struct.pack('<'+'I'*len(actual),*actual))})
  if fault:
   need(run['sabotage']['afterOriginalFence']==run['fences'][0]['id'] and run['fences'][1]['id']!=run['fences'][0]['id'],'physical mutation follows distinct original completion');need(run['sabotage']['method']=='texSubImage2D' and run['sabotage']['actualWrittenWords'][0]==(expected[0][0]^1),'actual native pixel mutation');need(not run['audit']['held'] and 'unchanged original integer/modifier/query full output oracle' in a['error'],'unchanged promoted assertion caught real pixel')
  else:need(run['audit']['held'],'native original oracle')
 need(len(set(ids))==len(ids),'unique actual physical sync identities');need(bool(mismatches)==fault,'physical wrong-pixel control');return {'path':name+'/report.json','reportSha256':sha(path.read_bytes()),'status':'HELD','nativeSourcePlanes':planes,'sourceWords':sourcewords,'outputWords':outputwords,'syncIdentities':ids,'mismatches':mismatches}
result={'schema':'d32-independent-fresh-native-word-audit-v1','status':'HELD','records':[audit('novel-native',False),audit('sabotage-post-completion',True)]};(OUT/'fresh-native-audit.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
